<div class="wp-block-wdl-lw-pr-custom-title-11 lw-pr-custom-title-11" style="--color-main:#0e5c55;--color-main-text:#ffffff;--color-sub-text:#cfe6e2;width:100%;margin:1em auto"><h2 class="ttl" style="border-radius:4px"><span class="sub">WHICH ONE</span><span class="main">どれを選べばいいか</span></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-11 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#1f2b2a;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">迷ったら、ひとつ下のプランから始めてください。<span class="lw-br on_500px"></span>足りなくなってから上げるほうが、無駄がありません。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-column-1 {"columnsPc":3,"columnWidthsPc":[1,1,1],"columnsSp":1,"rowGapPc":16,"columnGapPc":16,"rowGapSp":12,"itemBgNone":false,"itemBgTypePc":"solid","itemBgColorPc":"#eef4f2","itemBgTypeSp":"solid","itemBgColorSp":"#eef4f2","itemBorderColorPc":"#c9dcd7","itemBorderWidthPc":1,"itemBorderStylePc":"solid","itemBorderColorSp":"#c9dcd7","itemBorderWidthSp":1,"itemBorderStyleSp":"solid","itemPaddingTopPc":26,"itemPaddingBottomPc":26,"itemPaddingLeftPc":22,"itemPaddingRightPc":22,"itemPaddingTopSp":20,"itemPaddingBottomSp":20,"itemPaddingLeftSp":18,"itemPaddingRightSp":18,"itemBorderRadiusTopLeftPc":8,"itemBorderRadiusTopRightPc":8,"itemBorderRadiusBottomRightPc":8,"itemBorderRadiusBottomLeftPc":8,"itemBorderRadiusTopLeftSp":8,"itemBorderRadiusTopRightSp":8,"itemBorderRadiusBottomRightSp":8,"itemBorderRadiusBottomLeftSp":8} -->
<div class="wp-block-wdl-lw-pr-column-1 lw-pr-column-1" style="--column-1-wrap-padding-pc:0px 0px 0px 0px;--column-1-wrap-padding-sp:0px 0px 0px 0px;--column-1-border-color-pc:rgb(131, 131, 131);--column-1-border-width-pc:0px;--column-1-border-style-pc:solid;--column-1-border-color-sp:rgb(131, 131, 131);--column-1-border-width-sp:0px;--column-1-border-style-sp:solid;--column-1-bdr-pc:0px 0px 0px 0px;--column-1-bdr-sp:0px 0px 0px 0px;--column-1-gtc-pc:1fr 1fr 1fr;--column-1-gtc-sp:1fr;--column-1-row-gap-pc:16px;--column-1-row-gap-sp:12px;--column-1-column-gap-pc:16px;--column-1-column-gap-sp:16px;--column-1-item-bg-pc:#eef4f2;--column-1-item-bg-sp:#eef4f2;--column-1-item-min-h-pc:0px;--column-1-item-min-h-sp:0px;--column-1-item-padding-pc:26px 22px 26px 22px;--column-1-item-padding-sp:20px 18px 20px 18px;--column-1-item-bdr-pc:8px 8px 8px 8px;--column-1-item-bdr-sp:8px 8px 8px 8px;--column-1-item-border-color-pc:#c9dcd7;--column-1-item-border-width-pc:1px;--column-1-item-border-style-pc:solid;--column-1-item-border-color-sp:#c9dcd7;--column-1-item-border-width-sp:1px;--column-1-item-border-style-sp:solid"><div class="custom_wrap"><!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#063733;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">ひとりでやっている</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"15px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:15px;line-height:1.9;margin-top:0px;margin-bottom:0px">ご自身だけで店や事務所をされているなら「ひとり」で足ります。あとからスタッフが増えたときに、その月から上げれば大丈夫です。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item -->
<!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#063733;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">スタッフがいる</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"15px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:15px;line-height:1.9;margin-top:0px;margin-bottom:0px">2人以上で使うなら「おみせ」です。人によって売上を見せる／見せないを分けられるのはこのプランからです。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item -->
<!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#063733;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">お店が2つ以上ある</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"15px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:15px;line-height:1.9;margin-top:0px;margin-bottom:0px">店舗ごとに予約と売上を分けたいなら「チーム」です。5店舗までは追加の料金がかかりません。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item --></div></div>
